SELECT COUNT(*)
FROM LECTURE
WHERE LEC_ID = #{lecId}
  AND LMS_PRF_ID = #{professorLmsPrfId}

SELECT COUNT(*)
FROM LECTURE_ASSIGNMENT asn
JOIN LECTURE l ON l.LEC_ID = asn.LEC_ID
WHERE asn.LEC_ASN_ID = #{assignmentId}
  AND l.LMS_PRF_ID = #{professorLmsPrfId}

SELECT COUNT(*)
FROM LECTURE_ASSIGNMENT asn
JOIN LECTURE l ON l.LEC_ID = asn.LEC_ID
WHERE l.LMS_PRF_ID = #{professorLmsPrfId}
  AND asn.LEC_ID = #{lecId}


WHERE l.LMS_PRF_ID = #{professorLmsPrfId}
  AND asn.LEC_ID = #{lecId}
ORDER BY asn.LEC_ASN_DUE_DATE DESC, asn.LEC_ASN_ID DESC
OFFSET #{offset} ROWS FETCH NEXT #{size} ROWS ONLY

mapper.update:
UPDATE LECTURE_ASSIGNMENT
SET LEC_ASN_TITLE    = #{title},
    LEC_ASN_DUE_DATE = TO_TIMESTAMP(#{dueDate}, 'YYYY-MM-DD"T"HH24:MI'),
    LEC_ASN_CONTENT  = #{description, jdbcType=CLOB}
WHERE LEC_ASN_ID = #{assignmentId}

UPDATE LECTURE_ASSIGNMENT_ATTACHMENT
SET ATT_VAL_STATUS = 'DEL'
WHERE LEC_ASN_ATT_ID = #{attachmentId}
  AND LEC_ASN_ID = #{assignmentId}
  AND ATT_VAL_STATUS = 'ACT'
